SELECT CASE WHEN ss.revenue >= 4100 THEN 'high' WHEN ss.revenue >= 500 THEN 'mid' ELSE 'low' END AS revenue_bucket, ss.product_id, AVG(i.quantity) AS avg_quantity, ROUND(STDDEV(i.quantity), 2) AS stddev_quantity FROM inventory i JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY CASE WHEN ss.revenue >= 4100 THEN 'high' WHEN ss.revenue >= 500 THEN 'mid' ELSE 'low' END, ss.product_id HAVING AVG(i.quantity) > 100
